def range_sales(n_minutes, ops):
    n = n_minutes
    tree = [0] * (n + 1)                # Fenwick tree over minutes, 1-based

    def add(i, v):
        i += 1
        while i <= n:
            tree[i] += v
            i += i & -i

    def prefix(i):                      # total of minutes 0 .. i-1
        s = 0
        while i > 0:
            s += tree[i]
            i -= i & -i
        return s

    txns = {}                           # txn_id -> [minute, cents, counted]
    void_first = set()                  # voids that arrived before their sale
    out = []
    for op in ops:
        kind = op[0]
        if kind == 'query':
            lo, hi = op[1], op[2]
            out.append(prefix(hi + 1) - prefix(lo) if lo <= hi else 0)
        elif kind == 'sale':
            _, tid, minute, cents = op
            counted = tid not in void_first
            txns[tid] = [minute, cents, counted]
            if counted:
                add(minute, cents)
        elif kind == 'void':
            t = txns.get(op[1])
            if t is None:
                void_first.add(op[1])
            elif t[2]:
                t[2] = False
                add(t[0], -t[1])
        else:                           # move
            t = txns.get(op[1])
            if t is not None:
                if t[2]:
                    add(t[0], -t[1])
                    add(op[2], t[1])
                t[0] = op[2]
    return out

